window.AUTH=window.AUTH||{};window.AUTH["12-562"]={"d":"12-562","id":"2013/12-562","n":"United States v. Woods","src":["osg"],"briefs":[{"k":"petitioner","label":"Brief for the United States","date":"","url":"https://www.justice.gov/osg/media/224871/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/united-states-v-woods-brief-merits","n":96},{"k":"reply","label":"Reply brief for the United States","date":"2013-08-19","url":"https://www.justice.gov/osg/media/207001/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/united-states-v-woods-reply-merits","n":46}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep571/usrep571031/usrep571031.pdf","tr":true,"items":[{"t":"case","label":"Arbaugh v. Y & H Corp.","cite":"546 U.S. 500","y":2006,"id":"2005/04-944","sc":1,"sum":"The Court held that the number-of-employees requirement is an element of the merits of a Title VII claim, not a jurisdictional limitation.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Bemont Invs., L.L.C. v. United States","cite":"679 F.3d 339","y":2012,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/679/339/","op":4,"by":{"0":"20, 45, 47","1":"20"}},{"t":"case","label":"Braunstein v. Commissioner","cite":"374 U.S. 65","y":1963,"id":"1962/476","sc":1,"sum":"Under § 117 (m) of the Internal Revenue Code of 1939, the resulting gains to the taxpayers must be treated as ordinary income, instead of long-term capital gains, since the corporations were \"collapsible\" within the meaning of that section. Pp. 65-73. 305 F. 2d 949, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24, 40"}},{"t":"case","label":"Callaway v. Commissioner","cite":"231 F.3d 106","y":2000,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/231/106/","by":{"0":"8"}},{"t":"case","label":"Chef ’s Choice Produce, Ltd. v. Commissioner","cite":"95 T.C. 388","y":1990,"url":"https://www.courtlistener.com/c/T.C./95/388/","by":{"0":"9"}},{"t":"case","label":"Chevron U.S.A. Inc. v. NRDC","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"Commissioner v. Brown","cite":"380 U.S. 563","y":1965,"id":"1964/63","sc":1,"sum":"Respondent Brown, members of his family and three others, who owned substantially all the stock of a lumber milling company, of which Brown was president, sold their stock to a tax-exempt charitable organization (Institute) for $1,300,000. Institute paid $5,000 down from the company's assets. Concomitantly with the transfer, Institute liquidated the company and leased its assets for five years to a new,corporation …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Duffie v. United States","cite":"600 F.3d 362","y":2010,"url":"https://www.courtlistener.com/c/F.3d/600/362/","by":{"0":"11, 30"}},{"t":"case","label":"Fidelity Int’l Currency Advisor A Fund, LLC v. United States","cite":"661 F.3d 667","y":2011,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/661/667/","by":{"0":"15, 49"}},{"t":"case","label":"Cases:—Continued Gustashaw v. Commissioner","cite":"696 F.3d 1124","y":2012,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/696/1124/","by":{"0":"42"}},{"t":"case","label":"Heasley v. Commissioner","cite":"902 F.2d 380","y":1990,"url":"https://www.courtlistener.com/c/F.2d/902/380/","by":{"0":"19, 20, 47"}},{"t":"case","label":"Home Concrete & Supply, LLC v. United States","cite":"634 F.3d 249","y":2011,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/634/249/","by":{"0":"32"}},{"t":"case","label":"Jade Trading, LLC v. United States","cite":"598 F.3d 1372","y":2010,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/598/1372/","op":2,"by":{"0":"21, 27, 32, 33, 34","1":"3"}},{"t":"case","label":"Keener v. Commissioner","cite":"551 F.3d 1358","y":2009,"url":"https://www.courtlistener.com/c/F.3d/551/1358/","by":{"0":"30"}},{"t":"case","label":"Keller v. Commissioner","cite":"556 F.3d 1056","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/556/1056/","op":1,"by":{"0":"50"}},{"t":"case","label":"Mayo Found. for Med. Educ. & Research v. United States","cite":"131 S. Ct. 704","y":2011,"id":"2010/09-837","sc":1,"sum":"A case in which the Court upheld the Treasury Department's rule that treats medical residents as full-time employees, and therefore not exempt from the payment of payroll taxes.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"Morales v. Trans World Airlines, Inc.","cite":"504 U.S. 374","y":1992,"id":"1991/90-1604","sc":1,"sum":"The Court held that the Airline Deregulation Act of 1978 prevents states from prohibiting deceptive airline fare advertisements through enforcement of their general consumer protection statuses.","sumSrc":"Oyez","by":{"0":"32","1":"3"}},{"t":"case","label":"Napoliello v. Commissioner","cite":"655 F.3d 1060","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/655/1060/","by":{"0":"30"}},{"t":"case","label":"Petaluma FX Partners, LLC v. Commissioner","cite":"591 F.3d 649","y":2010,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/591/649/","op":3,"by":{"0":"passim"}},{"t":"case","label":"RA Invs. I, LLC v. Deutsche Bank AG","cite":"2005 WL 1356446","y":2005,"court":"N.D. Tex. June 6","by":{"0":"14"}},{"t":"case","label":"RJT Invs. X v. Commissioner","cite":"491 F.3d 732","y":2007,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/491/732/","by":{"0":"30"}},{"t":"case","label":"Tigers Eye Trading, LLC v. Commissioner","cite":"138 T.C. 67","y":2012,"url":"https://www.courtlistener.com/c/T.C./138/67/","by":{"0":"11, 13, 15, 28"}},{"t":"case","label":"Todd v. Commissioner","cite":"862 F.2d 540","y":1988,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/862/540/","by":{"0":"passim","1":"18"}},{"t":"case","label":"United States v. Arthur Young & Co.","cite":"465 U.S. 805","y":1984,"id":"1983/82-687","sc":1,"sum":"Respondent certified public accountant firm, as the independent auditor for respondent corporation, was responsible for reviewing the corporation's financial statements as required by the federal securities laws. In the course of reviewing these statements, the accounting firm verified the corporation's statement of its contingent tax liabilities, and, in so doing, prepared tax accrual workpapers relating to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2"}},{"t":"case","label":"United States v. Basye","cite":"410 U.S. 441","y":1973,"id":"1972/71-1022","sc":1,"sum":"The retirement fund payments, notwithstanding the fact that they were contributed directly to the trust, were compensation for services that Permanente rendered under the medical-service agreement and should have been reported as income to Permanente; and the individual partners should have included their shares of that income in their individual returns, since the existence of conditions upon the actual receipt by …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"sum":"The Court held that the \"administrative implementation of a particular statutory provision qualifies for [the greatest level of deference accorded under Chevron U.S.A. Inc. v. Natural Resources Defense Council] when it appears that Congress delegated authority to the agency generally to make rules carrying the force of law, and that the agency interpretation claiming deference was promulgated in the exercise of that authority.\" Justice Souter wrote that \"a tariff classification has no claim to judicial deference under Chevron, there being no indication that Congress intended such a ruling to carry the force of law, but we hold that under Skidmore v. Swift & Co., the ruling is eligible to claim respect according to its persuasiveness.\".","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Washington Mut. Inc. v. United States","cite":"636 F.3d 1207","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/636/1207/","by":{"0":"3"}},{"t":"law","label":"Pub. L. No. 97-34","url":"https://www.govinfo.gov/link/statute/95/172","by":{"0":"5"}},{"t":"law","label":"Improved Penalty Administration and Compliance Tax Act, Pub. L. No. 101-239","url":"https://www.govinfo.gov/link/statute/103/2388","by":{"0":"5"}},{"t":"usc","label":"26 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/26/1","stext":{"head":"§1. Tax imposed","paras":[[0,"(a) Married individuals filing joint returns and surviving spouses"],[0,"There is hereby imposed on the taxable income of—"],[1,"(1) every married individual (as defined in section 7703) who makes a single return jointly with his spouse under section 6013, and"],[1,"(2) every surviving spouse (as defined in section 2(a)),"],[0,"a tax determined in accordance with the following table:"],[0,"(b) Heads of households"],[0,"There is hereby imposed on the taxable income of every head of a household (as defined in section 2(b)) a tax determined in accordance with the following table:"],[0,"(c) Unmarried individuals (other than surviving spouses and heads of households)"],[0,"There is hereby imposed on the taxable income of every individual (other than a surviving spouse as defined in section 2(a) or the head of a household as defined in section 2(b)) who is not a married individual (as defined in section 7703) a tax determined in accordance with the following table:"],[0,"(d) Married individuals filing separate returns"],[0,"There is hereby imposed on the taxable income of every married individual (as defined in section 7703) who does not make a single return jointly with his spouse under section 6013, a tax determined in accordance with the following table:"],[0,"(e) Estates and trusts"],[0,"There is hereby imposed on the taxable income of—"],[1,"(1) every estate, and"],[1,"(2) every trust,"],[0,"taxable under this subsection a tax determined in accordance with the following table:"],[0,"(f) Phaseout of marriage penalty in 15-percent bracket; adjustments in tax tables so that inflation will not result in tax increases"],[0,"(1) In general"],[1,"Not later than December 15 of 1993, and each subsequent calendar year, the Secretary shall prescribe tables which shall apply in lieu of the tables contained in subsections (a), (b), (c), (d), and (e) with respect to taxable years beginning in the succeeding calendar year."],[0,"(2) Method of prescribing tables"],[1,"The table which under paragraph (1) is to apply in lieu of the table contained in subsection (a), (b), (c), (d), or (e), as the case may be, with respect to taxable years beginning in any calendar year shall be prescribed—"],[2,"(A) except as provided in paragraph (8), by increasing the minimum and maximum dollar amounts for each bracket for which a tax is imposed under such table by the cost-of-living adjustment for such calendar year, determined—"],[3,"(i) except as provided in clause (ii), by substituting \"1992\" for \"2016\" in paragraph (3)(A)(ii), and"],[3,"(ii) in the case of adjustments to the dollar amounts at which the 36 percent rate bracket begins or at which the 39.6 percent rate bracket begins, by substituting \"1993\" for \"2016\" in paragraph (3)(A)(ii),"],[2,"(B) by not changing the rate applicable to any rate bracket as adjusted under subparagraph (A), and"],[2,"(C) by adjusting the amounts setting forth the tax to the extent necessary to reflect the adjustments in the rate brackets."],[0,"(3) Cost-of-living adjustment"],[1,"For purposes of this subsection—"],[0,"(A) In general"],[2,"The cost-of-living adjustment for any calendar year is the percentage (if any) by which—"],[3,"(i) the C-CPI-U for the preceding calendar year, exceeds"],[3,"(ii) the CPI for calendar year 2016, multiplied by the amount determined under subparagraph (B)."],[0,"(B) Amount determined"],[2,"The amount determined under this clause is the amount obtained by dividing—"],[3,"(i) the C-CPI-U for calendar year 2016, by"],[3,"(ii) the CPI for calendar year 2016."],[0,"(C) Special rule for adjustments with a base year after 2016"],[2,"For purposes of any provision of this title which provides for the substitution of a year after 2016 for \"2016\" in subparagraph (A)(ii), subparagraph (A) shall be applied by substituting \"the C-CPI-U for calendar year 2016\" for \"the CPI for calendar year 2016\" and all that follows in clause (ii) thereof."],[0,"(4) CPI for any calendar year"],[1,"For purposes of paragraph (3), the CPI for any calendar year is the average of the Consumer Price Index as of the close of the 12-month period ending on August 31 of such calendar year."],[0,"(5) Consumer Price Index"],[1,"For purposes of paragraph (4), the term \"Consumer Price Index\" means the last Consumer Price Index for all-urban consumers published by the Department of Labor. For purposes of the preceding sentence, the revision of the Consumer Price Index which is most consistent with the Consumer Price Index for calendar year 1986 shall be used."],[0,"(6) C-CPI-U"],[1,"For purposes of this subsection—"],[0,"(A) In general"],[2,"The term \"C-CPI-U\" means the Chained Consumer Price Index for All Urban Consumers (as published by the Bureau of Labor Statistics of the Department of Labor). The values of the Chained Consumer Price Index for All Urban Consumers taken into account for purposes of determining the cost-of-living adjustment for any calendar year under this subsection shall be the latest values so published as of the date on which such Bureau publishes the initial value of the Chained Consumer Price Index for All Urban Consumers for the month of August for the preceding calendar year."],[0,"(B) Determination for calendar year"],[2,"The C-CPI-U for any calendar year is the average of the C-CPI-U as of the close of the 12-month period ending on August 31 of such calendar year."],[0,"(7) Rounding"],[0,"(A) In general"],[2,"If any increase determined under paragraph (2)(A), section 63(c)(4), section 68(b)(2) or section 151(d)(4) is not a multiple of $50, such increase shall be rounded to the next lowest multiple of $50."],[0,"(B) Table for married individuals filing separately"],[2,"In the case of a married individual filing a separate return, subparagraph (A) (other than with respect to sections 63(c)(4) and 151(d)(4)(A)) shall be applied by substituting \"$25\" for \"$50\" each place it appears."],[0,"(8) Elimination of marriage penalty in 15-percent bracket"],[1,"With respect to taxable years beginning after December 31, 2003, in prescribing the tables under paragraph (1)—"],[2,"(A) the maximum taxable income in the 15-percent rate bracket in the table contained in subsection (a) (and the minimum taxable income in the next higher taxable income bracket in such table) shall be 200 percent of the maximum taxable income in the 15-percent rate bracket in the table contained in subsection (c) (after any other adjustment under this subsection), and"],[2,"(B) the comparable taxable income amounts in the table contained in subsection (d) shall be ½ of the amounts determined under subparagraph (A)."],[0,"(g) Certain unearned income of children taxed as if parent's income"],[0,"(1) In general"],[1,"In the case of any child to whom this subsection applies, the tax imposed by this section shall be equal to the greater of—"],[2,"(A) the tax imposed by this section without regard to this subsection, or"],[2,"(B) the sum of—"],[3,"(i) the tax which would be imposed by this section if the taxable income of such child for the taxable year were reduced by the net unearned income of such child, plus"],[3,"(ii) such child's share of the allocable parental tax."],[0,"(2) Child to whom subsection applies"],[1,"This subsection shall apply to any child for any taxable year if—"],[2,"(A) such child—"],[3,"(i) has not attained age 18 before the close of the taxable year, or"],[3,"(ii)(I) has attained age 18 before the close of the taxable year and meets the age requirements of section 152(c)(3) (determined without regard to subparagraph (B) thereof), and"],[3,"(II) whose earned income (as defined in section 911(d)(2)) for such taxable year does not exceed one-half of the amount of the individual's support (within the meaning of section 152(c)(1)(D) after the application of section 152(f)(5) (without regard to subparagraph (A) thereof)) for such taxable year,"],[2,"(B) either parent of such child is alive at the close of the taxable year, and"],[2,"(C) such child does not file a joint return for the taxable year."],[0,"(3) Allocable parental tax"],[1,"For purposes of this subsection—"],[0,"(A) In general"],[2,"The term \"allocable parental tax\" means the excess of—"],[3,"(i) the tax which would be imposed by this section on the parent's taxable income if such income included the net unearned income of all children of the parent to whom this subsection applies, over"],[3,"(ii) the tax imposed by this section on the parent without regard to this subsection."],[2,"For purposes of clause (i), net unearned income of all children of the parent shall not be taken into account in computing any exclusion, deduction, or credit of the parent."],[0,"(B) Child's share"],[2,"A child's share of any allocable parental tax of a parent shall be equal to an amount which bears the same ratio to the total allocable parental tax as the child's net unearned income bears to the aggregate net unearned income of all children of such parent to whom this subsection applies."],[0,"(C) Special rule where parent has different taxable year"],[2,"Except as provided in regulations, if the parent does not have the same taxable year as the child, the allocable parental tax shall be determined on the basis of the taxable year of the parent ending in the child's taxable year."],[0,"(4) Net unearned income"],[1,"For purposes of this subsection—"],[0,"(A) In general"],[2,"The term \"net unearned income\" means the excess of—"],[3,"(i) the portion of the adjusted gross income for the taxable year which is not attributable to earned income (as defined in section 911(d)(2)), over"],[3,"(ii) the sum of—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/1?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1. Tax imposed","tname":"Internal Revenue Code","by":{"0":"7","1":"14"}},{"t":"usc","label":"26 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/26/701","stext":{"head":"§701. Partners, not partnership, subject to tax","paras":[[0,"A partnership as such shall not be subject to the income tax imposed by this chapter. Persons carrying on business as partners shall be liable for income tax only in their separate or individual capacities."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/701?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§701. Partners, not partnership, subject to tax","tname":"Internal Revenue Code","by":{"0":"7"}},{"t":"usc","label":"26 U.S.C. § 702","url":"https://www.law.cornell.edu/uscode/text/26/702","subs":["(a)"],"stext":{"head":"§702. Income and credits of partner","paras":[[0,"(a) General rule"],[0,"In determining his income tax, each partner shall take into account separately his distributive share of the partnership's—"],[1,"(1) gains and losses from sales or exchanges of capital assets held for not more than 1 year,"],[1,"(2) gains and losses from sales or exchanges of capital assets held for more than 1 year,"],[1,"(3) gains and losses from sales or exchanges of property described in section 1231 (relating to certain property used in a trade or business and involuntary conversions),"],[1,"(4) charitable contributions (as defined in section 170(c)),"],[1,"(5) dividends with respect to which section 1(h)(11) or part VIII of subchapter B applies,"],[1,"(6) taxes, described in section 901, paid or accrued to foreign countries and to possessions of the United States,"],[1,"(7) other items of income, gain, loss, deduction, or credit, to the extent provided by regulations prescribed by the Secretary, and"],[1,"(8) taxable income or loss, exclusive of items requiring separate computation under other paragraphs of this subsection."],[0,"(b) Character of items constituting distributive share"],[0,"The character of any item of income, gain, loss, deduction, or credit included in a partner's distributive share under paragraphs (1) through (7) of subsection (a) shall be determined as if such item were realized directly from the source from which realized by the partnership, or incurred in the same manner as incurred by the partnership."],[0,"(c) Gross income of a partner"],[0,"In any case where it is necessary to determine the gross income of a partner for purposes of this title, such amount shall include his distributive share of the gross income of the partnership."],[0,"(d) Cross reference"],[2,"For rules relating to procedures for determining the tax treatment of partnership items see subchapter C of chapter 63 (section 6221 and following)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/702?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§702. Income and credits of partner","tname":"Internal Revenue Code","by":{"0":"7"}},{"t":"usc","label":"26 U.S.C. § 705","url":"https://www.law.cornell.edu/uscode/text/26/705","subs":["(a)"],"stext":{"head":"§705. Determination of basis of partner's interest","paras":[[0,"(a) General rule"],[0,"The adjusted basis of a partner's interest in a partnership shall, except as provided in subsection (b), be the basis of such interest determined under section 722 (relating to contributions to a partnership) or section 742 (relating to transfers of partnership interests)—"],[1,"(1) increased by the sum of his distributive share for the taxable year and prior taxable years of—"],[2,"(A) taxable income of the partnership as determined under section 703(a),"],[2,"(B) income of the partnership exempt from tax under this title, and"],[2,"(C) the excess of the deductions for depletion over the basis of the property subject to depletion;"],[1,"(2) decreased (but not below zero) by distributions by the partnership as provided in section 733 and by the sum of his distributive share for the taxable year and prior taxable years of—"],[2,"(A) losses of the partnership, and"],[2,"(B) expenditures of the partnership not deductible in computing its taxable income and not properly chargeable to capital account; and"],[1,"(3) decreased (but not below zero) by the amount of the partner's deduction for depletion for any partnership oil and gas property to the extent such deduction does not exceed the proportionate share of the adjusted basis of such property allocated to such partner under section 613A(c)(7)(D)."],[0,"(b) Alternative rule"],[0,"The Secretary shall prescribe by regulations the circumstances under which the adjusted basis of a partner's interest in a partnership may be determined by reference to his proportionate share of the adjusted basis of partnership property upon a termination of the partnership."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/705?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§705. Determination of basis of partner's interest","tname":"Internal Revenue Code","by":{"0":"15"}},{"t":"usc","label":"26 U.S.C. § 722","url":"https://www.law.cornell.edu/uscode/text/26/722","stext":{"head":"§722. Basis of contributing partner's interest","paras":[[0,"The basis of an interest in a partnership acquired by a contribution of property, including money, to the partnership shall be the amount of such money and the adjusted basis of such property to the contributing partner at the time of the contribution increased by the amount (if any) of gain recognized under section 721(b) to the contributing partner at such time."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/722?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§722. Basis of contributing partner's interest","tname":"Internal Revenue Code","by":{"0":"15"}},{"t":"usc","label":"26 U.S.C. § 732","url":"https://www.law.cornell.edu/uscode/text/26/732","subs":["(b)"],"by":{"0":"16, 32"}},{"t":"usc","label":"26 U.S.C. § 733","url":"https://www.law.cornell.edu/uscode/text/26/733","by":{"0":"15"}},{"t":"usc","label":"26 U.S.C. § 752","url":"https://www.law.cornell.edu/uscode/text/26/752","subs":["(a)","(b)"],"by":{"0":"15, 15"}},{"t":"usc","label":"26 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/26/1001","subs":["(a)"],"by":{"0":"3, 40"}},{"t":"usc","label":"26 U.S.C. § 1366","url":"https://www.law.cornell.edu/uscode/text/26/1366","by":{"0":"17"}},{"t":"usc","label":"26 U.S.C. § 6011","url":"https://www.law.cornell.edu/uscode/text/26/6011","subs":["(a)"],"by":{"0":"2"}},{"t":"usc","label":"26 U.S.C. § 6012","url":"https://www.law.cornell.edu/uscode/text/26/6012","subs":["(a)"],"by":{"0":"2"}},{"t":"usc","label":"26 U.S.C. § 6031","url":"https://www.law.cornell.edu/uscode/text/26/6031","subs":["(a)"],"by":{"0":"7"}},{"t":"usc","label":"26 U.S.C. § 6211","url":"https://www.law.cornell.edu/uscode/text/26/6211","stext":{"head":"§6211. Definition of a deficiency","paras":[[0,"(a) In general"],[0,"For purposes of this title in the case of income, estate, and gift taxes imposed by subtitles A and B and excise taxes imposed by chapters 41, 42, 43, and 44 the term \"deficiency\" means the amount by which the tax imposed by subtitle A or B, or chapter 41, 42, 43, or 44 exceeds the excess of—"],[1,"(1) the sum of"],[2,"(A) the amount shown as the tax by the taxpayer upon his return, if a return was made by the taxpayer and an amount was shown as the tax by the taxpayer thereon, plus"],[2,"(B) the amounts previously assessed (or collected without assessment) as a deficiency, over—"],[1,"(2) the amount of rebates, as defined in subsection (b)(2), made."],[0,"(b) Rules for application of subsection (a)"],[0,"For purposes of this section—"],[1,"(1) The tax imposed by subtitle A and the tax shown on the return shall both be determined without regard to payments on account of estimated tax, without regard to the credit under section 31, without regard to the credit under section 33, and without regard to any credits resulting from the collection of amounts assessed under section 6851 or 6852 (relating to termination assessments)."],[1,"(2) The term \"rebate\" means so much of an abatement, credit, refund, or other repayment, as was made on the ground that the tax imposed by subtitle A or B or chapter 41, 42, 43, or 44 was less than the excess of the amount specified in subsection (a)(1) over the rebates previously made."],[1,"(3) The computation by the Secretary, pursuant to section 6014, of the tax imposed by chapter 1 shall be considered as having been made by the taxpayer and the tax so computed considered as shown by the taxpayer upon his return."],[1,"(4) For purposes of subsection (a)—"],[2,"(A) any excess of the sum of the credits allowable under sections 21 by reason of subsection (g) thereof, 24 by reason of subsections (d) and (i)(1) thereof, 25A by reason of subsection (i) thereof, 32, 34, 35, 36, 36B, 6428, 6428A, 6428B, and 7527A over the tax imposed by subtitle A (determined without regard to such credits), and"],[2,"(B) any excess of the sum of such credits as shown by the taxpayer on his return over the amount shown as the tax by the taxpayer on such return (determined without regard to such credits),"],[1,"shall be taken into account as negative amounts of tax."],[0,"(c) Coordination with subchapter C"],[0,"In determining the amount of any deficiency for purposes of this subchapter, adjustments to partnership-related items shall be made only as provided in subchapter C."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/6211?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§6211. Definition of a deficiency","tname":"Internal Revenue Code","by":{"0":"3"}},{"t":"usc","label":"26 U.S.C. § 6213","url":"https://www.law.cornell.edu/uscode/text/26/6213","subs":["(a)"],"by":{"0":"3"}},{"t":"usc","label":"26 U.S.C. § 6221","url":"https://www.law.cornell.edu/uscode/text/26/6221","stext":{"head":"§6221. Determination at partnership level","paras":[[0,"(a) In general"],[0,"Any adjustment to a partnership-related item shall be determined, and any tax attributable thereto shall be assessed and collected, and the applicability of any penalty, addition to tax, or additional amount which relates to an adjustment to any such item shall be determined, at the partnership level, except to the extent otherwise provided in this subchapter."],[0,"(b) Election out for certain partnerships with 100 or fewer partners, etc."],[0,"(1) In general"],[1,"This subchapter shall not apply with respect to any partnership for any taxable year if—"],[2,"(A) the partnership elects the application of this subsection for such taxable year,"],[2,"(B) for such taxable year the partnership is required to furnish 100 or fewer statements under section 6031(b) with respect to its partners,"],[2,"(C) each of the partners of such partnership is an individual, a C corporation, any foreign entity that would be treated as a C corporation were it domestic, an S corporation, or an estate of a deceased partner,"],[2,"(D) the election—"],[3,"(i) is made with a timely filed return for such taxable year, and"],[3,"(ii) includes (in the manner prescribed by the Secretary) a disclosure of the name and taxpayer identification number of each partner of such partnership, and"],[2,"(E) the partnership notifies each such partner of such election in the manner prescribed by the Secretary."],[0,"(2) Special rules relating to certain partners"],[0,"(A) S corporation partners"],[2,"In the case of a partner that is an S corporation—"],[3,"(i) the partnership shall only be treated as meeting the requirements of paragraph (1)(C) with respect to such partner if such partnership includes (in the manner prescribed by the Secretary) a disclosure of the name and taxpayer identification number of each person with respect to whom such S corporation is required to furnish a statement under section 6037(b) for the taxable year of the S corporation ending with or within the partnership taxable year for which the application of this subsection is elected, and"],[3,"(ii) the statements such S corporation is required to so furnish shall be treated as statements furnished by the partnership for purposes of paragraph (1)(B)."],[0,"(B) Foreign partners"],[2,"For purposes of paragraph (1)(D)(ii), the Secretary may provide for alternative identification of any foreign partners."],[0,"(C) Other partners"],[2,"The Secretary may by regulation or other guidance prescribe rules similar to the rules of subparagraph (A) with respect to any partners not described in such subparagraph or paragraph (1)(C)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/6221?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§6221. Determination at partnership level","tname":"Internal Revenue Code","by":{"0":"8, 12, 27, 28, 29, 30, 8","1":"9"}},{"t":"usc","label":"26 U.S.C. § 6222","url":"https://www.law.cornell.edu/uscode/text/26/6222","subs":["(a)","(b)(1)"],"by":{"0":"8, 36, 8, 36"}},{"t":"usc","label":"26 U.S.C. § 6223","url":"https://www.law.cornell.edu/uscode/text/26/6223","subs":["(a)","(a)(2)"],"by":{"0":"9, 9"}},{"t":"usc","label":"26 U.S.C. § 6224","url":"https://www.law.cornell.edu/uscode/text/26/6224","subs":["(a)"],"by":{"0":"9"}},{"t":"usc","label":"26 U.S.C. § 6225","url":"https://www.law.cornell.edu/uscode/text/26/6225","subs":["(a)"],"by":{"0":"9"}},{"t":"usc","label":"26 U.S.C. § 6226","url":"https://www.law.cornell.edu/uscode/text/26/6226","subs":["(a)","(b)","(c)","(d)"],"stext":{"head":"§6226. Alternative to payment of imputed underpayment by partnership","paras":[[0,"(a) In general"],[0,"If the partnership—"],[1,"(1) not later than 45 days after the date of the notice of final partnership adjustment, elects the application of this section with respect to an imputed underpayment, and"],[1,"(2) at such time and in such manner as the Secretary may provide, furnishes to each partner of the partnership for the reviewed year and to the Secretary a statement of the partner's share of any adjustment to a partnership-related item (as determined in the notice of final partnership adjustment),"],[0,"section 6225 shall not apply with respect to such underpayment (and no assessment of tax, levy, or proceeding in any court for the collection of such underpayment shall be made against such partnership) and each such partner shall take such adjustment into account as provided in subsection (b). The election under paragraph (1) shall be made in such manner as the Secretary may provide and, once made, shall be revocable only with the consent of the Secretary."],[0,"(b) Adjustments taken into account by partner"],[0,"(1) Tax imposed in year of statement"],[1,"Except as provided in paragraph (4), each partner's tax imposed by chapter 1 for the taxable year which includes the date the statement was furnished under subsection (a) shall be adjusted by the aggregate of the correction amounts determined under paragraph (2) for the taxable years referred to therein."],[0,"(2) Correction amounts"],[1,"The correction amounts determined under this paragraph are—"],[2,"(A) in the case of the taxable year of the partner which includes the end of the reviewed year, the amount by which the tax imposed under chapter 1 would increase or decrease if the partner's share of the adjustments described in subsection (a) were taken into account for such taxable year, and"],[2,"(B) in the case of any taxable year after the taxable year referred to in subparagraph (A) and before the taxable year referred to in paragraph (1), the amount by which the tax imposed under chapter 1 would increase or decrease by reason of the adjustment to tax attributes under paragraph (3)."],[0,"(3) Adjustment of tax attributes"],[1,"Any tax attribute which would have been affected if the adjustments described in subsection (a) were taken into account for the taxable year referred to in paragraph (2)(A) shall—"],[2,"(A) in the case of any taxable year referred to in paragraph (2)(B), be appropriately adjusted for purposes of applying such paragraph, and"],[2,"(B) in the case of any subsequent taxable year, be appropriately adjusted."],[0,"(4) Treatment of partnerships and S corporations in tiered structures"],[0,"(A) In general"],[2,"If a partner which receives a statement under subsection (a)(2) is a partnership or an S corporation, such partner shall, with respect to the partner's share of the adjustment—"],[3,"(i) file with the Secretary a partnership adjustment tracking report which includes such information as the Secretary may require, and"],[3,"(ii)(I) furnish statements under rules similar to the rules of subsection (a)(2), or"],[3,"(II) if no such statements are furnished, compute and pay an imputed underpayment under rules similar to the rules of section 6225 (other than paragraphs (2), (7), and (9) of subsection (c) thereof)."],[0,"(B) Due date"],[2,"For purposes of subparagraph (A), with respect to a partner's share of the adjustment, the partnership adjustment tracking report shall be filed, and the imputed underpayment shall be paid or statements shall be furnished, not later than the due date for the return for the adjustment year of the audited partnership."],[0,"(C) Partnership payment of tax if elected out of subchapter"],[2,"In the case of a partnership which has elected the application of section 6221(b) with respect to the taxable year of the partnership which includes the end of the reviewed year of the audited partnership, this paragraph shall apply notwithstanding such election."],[0,"(D) Audited partnership"],[2,"For purposes of this paragraph, the term \"audited partnership\" means, with respect to any partner described in subparagraph (A), the partnership in the chain of ownership originally electing the application of this section."],[0,"(E) Treatment of trusts"],[2,"The Secretary shall prescribe such rules as may be necessary with respect to trusts which receive a statement under subsection (a)(2)."],[0,"(c) Penalties and interest"],[0,"(1) Penalties"],[1,"Notwithstanding subsections (a) and (b), any penalties, additions to tax, or additional amount shall be determined as provided under section 6221 and the partners of the partnership for the reviewed year shall be liable for any such penalty, addition to tax, or additional amount."],[0,"(2) Interest"],[1,"In the case of an imputed underpayment with respect to which the application of this section is elected, or which is described in subsection (b)(4)(A)(ii)(I), interest shall be determined—"],[2,"(A) at the partner level,"],[2,"(B) from the due date of the return for the taxable year to which the increase is attributable (determined by taking into account any increases attributable to a change in tax attributes for a taxable year under subsection (b)(2)), and"],[2,"(C) at the underpayment rate under section 6621(a)(2), determined by substituting \"5 percentage points\" for \"3 percentage points\" in subparagraph (B) thereof."],[0,"(d) Judicial review"],[0,"For the time period within which a partnership may file a petition for a readjustment, see section 6234(a)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/6226?type=usc&year=mostrecent&link-type=html"},"head":"§6226. Alternative to payment of imputed underpayment by partnership","tname":"Internal Revenue Code","by":{"0":"27, 9, 18, 9, 9, 9, passim","1":"passim"}},{"t":"usc","label":"26 U.S.C. § 6230","url":"https://www.law.cornell.edu/uscode/text/26/6230","subs":["(a)","(a)(1)","(a)(2)","(a)(2)(A)(i)","(c)(1)","(c)(1)(A)","(c)(3)","(c)(4)","(c)(1)(C)"],"stext":{"head":"§6230. Additional administrative provisions","paras":[[0,"(a) Coordination with deficiency proceedings"],[0,"(1) In general"],[1,"Except as provided in paragraph (2) or (3), subchapter B of this chapter shall not apply to the assessment or collection of any computational adjustment."],[0,"(2) Deficiency proceedings to apply in certain cases"],[2,"(A) Subchapter B shall apply to any deficiency attributable to—"],[3,"(i) affected items which require partner level determinations (other than penalties, additions to tax, and additional amounts that relate to adjustments to partnership items), or"],[3,"(ii) items which have become nonpartnership items (other than by reason of section 6231(b)(1)(C)) and are described in section 6231(e)(1)(B)."],[2,"(B) Subchapter B shall be applied separately with respect to each deficiency described in subparagraph (A) attributable to each partnership."],[2,"(C) Notwithstanding any other law or rule of law, any notice or proceeding under subchapter B with respect to a deficiency described in this paragraph shall not preclude or be precluded by any other notice, proceeding, or determination with respect to a partner's tax liability for a taxable year."],[0,"(3) Special rule in case of assertion by partner's spouse of innocent spouse relief"],[1,"(A) Notwithstanding section 6404(b), if the spouse of a partner asserts that section 6015 applies with respect to a liability that is attributable to any adjustment to a partnership item (including any liability for any penalties, additions to tax, or additional amounts relating to such adjustment), then such spouse may file with the Secretary within 60 days after the notice of computational adjustment is mailed to the spouse a request for abatement of the assessment specified in such notice. Upon receipt of such request, the Secretary shall abate the assessment. Any reassessment of the tax with respect to which an abatement is made under this subparagraph shall be subject to the deficiency procedures prescribed by subchapter B. The period for making any such reassessment shall not expire before the expiration of 60 days after the date of such abatement."],[1,"(B) If the spouse files a petition with the Tax Court pursuant to section 6213 with respect to the request for abatement described in subparagraph (A), the Tax Court shall only have jurisdiction pursuant to this section to determine whether the requirements of section 6015 have been satisfied. For purposes of such determination, the treatment of partnership items (and the applicability of any penalties, additions to tax, or additional amounts) under the settlement, the final partnership administrative adjustment, or the decision of the court (whichever is appropriate) that gave rise to the liability in question shall be conclusive."],[1,"(C) Rules similar to the rules contained in subparagraphs (B) and (C) of paragraph (2) shall apply for purposes of this paragraph."],[0,"(b) Mathematical and clerical errors appearing on partnership return"],[0,"(1) In general"],[1,"Section 6225 shall not apply to any adjustment necessary to correct a mathematical or clerical error (as defined in section 6213(g)(2)) appearing on the partnership return."],[0,"(2) Exception"],[1,"Paragraph (1) shall not apply to a partner if, within 60 days after the day on which notice of the correction of the error is mailed to the partner, such partner files with the Secretary a request that the correction not be made."],[0,"(c) Claims arising out of erroneous computations, etc."],[0,"(1) In general"],[1,"A partner may file a claim for refund on the grounds that—"],[2,"(A) the Secretary erroneously computed any computational adjustment necessary—"],[3,"(i) to make the partnership items on the partner's return consistent with the treatment of the partnership items on the partnership return, or"],[3,"(ii) to apply to the partner a settlement, a final partnership administrative adjustment, or the decision of a court in an action brought under section 6226 or section 6228(a),"],[2,"(B) the Secretary failed to allow a credit or to make a refund to the partner in the amount of the overpayment attributable to the application to the partner of a settlement, a final partnership administrative adjustment, or the decision of a court in an action brought under section 6226 or section 6228(a), or"],[2,"(C) the Secretary erroneously imposed any penalty, addition to tax, or additional amount which relates to an adjustment to a partnership item."],[0,"(2) Time for filing claim"],[0,"(A) Under paragraph (1)(A) or (C)"],[2,"Any claim under subparagraph (A) or (C) of paragraph (1) shall be filed within 6 months after the day on which the Secretary mails the notice of computational adjustment to the partner."],[0,"(B) Under paragraph (1)(B)"],[2,"Any claim under paragraph (1)(B) shall be filed within 2 years after whichever of the following days is appropriate:"],[3,"(i) the day on which the settlement is entered into,"],[3,"(ii) the day on which the period during which an action may be brought under section 6226 with respect to the final partnership administrative adjustment expires, or"],[3,"(iii) the day on which the decision of the court becomes final."],[0,"(3) Suit if claim not allowed"],[1,"If any portion of a claim under paragraph (1) is not allowed, the partner may bring suit with respect to such portion within the period specified in subsection (a) of section 6532 (relating to periods of limitations on refund suits)."],[0,"(4) No review of substantive issues"],[1,"For purposes of any claim or suit under this subsection, the treatment of partnership items on the partnership return, under the settlement, under the final partnership administrative adjustment, or under the decision of the court (whichever is appropriate) shall be conclusive. In addition, the determination under the final partnership administrative adjustment or under the decision of the court (whichever is appropriate) concerning the applicability of any penalty, addition to tax, or additional amount which relates to an adjustment to a partnership item shall also be conclusive. Notwithstanding the preceding sentence, the partner shall be allowed to assert any partner level defenses that may apply or to challenge the amount of the computational adjustment."],[0,"(5) Rules for seeking innocent spouse relief"],[0,"(A) In general"],[2,"The spouse of a partner may file a claim for refund on the ground that the Secretary failed to relieve the spouse under section 6015 from a liability that is attributable to an adjustment to a partnership item (including any liability for any penalties, additions to tax, or additional amounts relating to such adjustment)."],[0,"(B) Time for filing claim"],[2,"Any claim under subparagraph (A) shall be filed within 6 months after the day on which the Secretary mails to the spouse the notice of computational adjustment referred to in subsection (a)(3)(A)."],[0,"(C) Suit if claim not allowed"],[2,"If the claim under subparagraph (B) is not allowed, the spouse may bring suit with respect to the claim within the period specified in paragraph (3)."],[0,"(D) Prior determinations are binding"],[2,"For purposes of any claim or suit under this paragraph, the treatment of partnership items (and the applicability of any penalties, additions to tax, or additional amounts) under the settlement, the final partnership administrative adjustment, or the decision of the court (whichever is appropriate) that gave rise to the liability in question shall be conclusive."],[0,"(d) Special rules with respect to credits or refunds attributable to partnership items"],[0,"(1) In general"],[1,"Except as otherwise provided in this subsection, no credit or refund of an overpayment attributable to a partnership item (or an affected item) for a partnership taxable year shall be allowed or made to any partner after the expiration of the period of limitation prescribed in section 6229 with respect to such partner for assessment of any tax attributable to such item."],[0,"(2) Administrative adjustment request"],[1,"If a request for an administrative adjustment under section 6227 with respect to a partnership item is timely filed, credit or refund of any overpayment attributable to such partnership item (or an affected item) may be allowed or made at any time before the expiration of the period prescribed in section 6228 for bringing suit with respect to such request."],[0,"(3) Claim under subsection (c)"],[1,"If a timely claim is filed under subsection (c) for a credit or refund of an overpayment attributable to a partnership item (or affected item), credit or refund of such overpayment may be allowed or made at any time before the expiration of the period specified in section 6532 (relating to periods of limitations on suits) for bringing suit with respect to such claim."],[0,"(4) Timely suit"],[1,"Paragraph (1) shall not apply to any credit or refund of any overpayment attributable to a partnership item (or an item affected by such partnership item) if a partner brings a timely suit with respect to a timely administrative adjustment request under section 6228 or a timely claim under subsection (c) relating to such overpayment."],[0,"(5) Overpayments refunded without requirement that partner file claim"],[1,"In the case of any overpayment by a partner which is attributable to a partnership item (or an affected item) and which may be refunded under this subchapter, to the extent practicable credit or refund of such overpayment shall be allowed or made without any requirement that the partner file a claim therefor."]],"more":true,"ed":"2016","src":"https://www.govinfo.gov/link/uscode/26/6230?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":1,"head":"§6230. Additional administrative provisions","tname":"Internal Revenue Code","by":{"0":"10, 10, 13, 23, 10, 11, 23, 10, 10, 23, 10, 13, 22, 23, 35","1":"9, 9, 6, 9"}},{"t":"usc","label":"26 U.S.C. § 6231","url":"https://www.law.cornell.edu/uscode/text/26/6231","subs":["(a)(2)(B)","(a)(3)","(a)(5)","(a)(6)","(a)(7)","(a)(8)","(a)(9)","(a)(10)","(a)(11)"],"by":{"0":"18, 8, 30, 10, 22, 33, 10, 11, 9, 9, 18, 18, 9"}},{"t":"usc","label":"26 U.S.C. § 6233","url":"https://www.law.cornell.edu/uscode/text/26/6233","by":{"0":"11"}},{"t":"usc","label":"26 U.S.C. § 6659","url":"https://www.law.cornell.edu/uscode/text/26/6659","subs":["(a)(1988)","(c)(1988)"],"by":{"0":"5, 5, 5"}},{"t":"usc","label":"26 U.S.C. § 6662","url":"https://www.law.cornell.edu/uscode/text/26/6662","subs":["(2000)","(a)(2000)","(b)(2000)","(b)(1)(2000)","(b)(3)(2000)","(c)(2000)","(e)(2000)","(e)(1)(A)(2000)","(e)(2)(2000)","(h)(1)(2000)","(h)(2)(A)(i)(2000)","(b)","(b)(1)","(b)(2)","(b)(3)","(b)(6)","(d)(2)(A)","(e)","(e)(1)(A)","(e)(1)(B)(i)","(i)"],"stext":{"head":"§6662. Imposition of accuracy-related penalty on underpayments","paras":[[0,"(a) Imposition of penalty"],[0,"If this section applies to any portion of an underpayment of tax required to be shown on a return, there shall be added to the tax an amount equal to 20 percent of the portion of the underpayment to which this section applies."],[0,"(b) Portion of underpayment to which section applies"],[0,"This section shall apply to the portion of any underpayment which is attributable to 1 or more of the following:"],[1,"(1) Negligence or disregard of rules or regulations."],[1,"(2) Any substantial understatement of income tax."],[1,"(3) Any substantial valuation misstatement under chapter 1."],[1,"(4) Any substantial overstatement of pension liabilities."],[1,"(5) Any substantial estate or gift tax valuation understatement."],[1,"(6) Any disallowance of claimed tax benefits by reason of a transaction lacking economic substance (within the meaning of section 7701(o)) or failing to meet the requirements of any similar rule of law."],[1,"(7) Any undisclosed foreign financial asset understatement."],[1,"(8) Any inconsistent estate basis."],[1,"(9) Any overstatement of the deduction provided in section 170(p)."],[1,"(10) Any disallowance of a deduction by reason of section 170(h)(7)."],[0,"This section shall not apply to any portion of an underpayment on which a penalty is imposed under section 6663. Except as provided in paragraph (1) or (2)(B) of section 6662A(e), this section shall not apply to the portion of any underpayment which is attributable to a reportable transaction understatement on which a penalty is imposed under section 6662A."],[0,"(c) Negligence"],[0,"For purposes of this section, the term \"negligence\" includes any failure to make a reasonable attempt to comply with the provisions of this title, and the term \"disregard\" includes any careless, reckless, or intentional disregard."],[0,"(d) Substantial understatement of income tax"],[0,"(1) Substantial understatement"],[0,"(A) In general"],[2,"For purposes of this section, there is a substantial understatement of income tax for any taxable year if the amount of the understatement for the taxable year exceeds the greater of—"],[3,"(i) 10 percent of the tax required to be shown on the return for the taxable year, or"],[3,"(ii) $5,000."],[0,"(B) Special rule for corporations"],[2,"In the case of a corporation other than an S corporation or a personal holding company (as defined in section 542), there is a substantial understatement of income tax for any taxable year if the amount of the understatement for the taxable year exceeds the lesser of—"],[3,"(i) 10 percent of the tax required to be shown on the return for the taxable year (or, if greater, $10,000), or"],[3,"(ii) $10,000,000."],[0,"(C) Special rule for taxpayers claiming section 199A deduction"],[2,"In the case of any taxpayer who claims any deduction allowed under section 199A for the taxable year, subparagraph (A) shall be applied by substituting \"5 percent\" for \"10 percent\"."],[0,"(2) Understatement"],[0,"(A) In general"],[2,"For purposes of paragraph (1), the term \"understatement\" means the excess of—"],[3,"(i) the amount of the tax required to be shown on the return for the taxable year, over"],[3,"(ii) the amount of the tax imposed which is shown on the return, reduced by any rebate (within the meaning of section 6211(b)(2))."],[2,"The excess under the preceding sentence shall be determined without regard to items to which section 6662A applies."],[0,"(B) Reduction for understatement due to position of taxpayer or disclosed item"],[2,"The amount of the understatement under subparagraph (A) shall be reduced by that portion of the understatement which is attributable to—"],[3,"(i) the tax treatment of any item by the taxpayer if there is or was substantial authority for such treatment, or"],[3,"(ii) any item if—"],[4,"(I) the relevant facts affecting the item's tax treatment are adequately disclosed in the return or in a statement attached to the return, and"],[4,"(II) there is a reasonable basis for the tax treatment of such item by the taxpayer."],[2,"For purposes of clause (ii)(II), in no event shall a corporation be treated as having a reasonable basis for its tax treatment of an item attributable to a multiple-party financing transaction if such treatment does not clearly reflect the income of the corporation."],[0,"(C) Reduction not to apply to tax shelters"],[0,"(i) In general"],[3,"Subparagraph (B) shall not apply to any item attributable to a tax shelter."],[0,"(ii) Tax shelter"],[3,"For purposes of clause (i), the term \"tax shelter\" means—"],[4,"(I) a partnership or other entity,"],[4,"(II) any investment plan or arrangement, or"],[4,"(III) any other plan or arrangement,"],[0,"if a significant purpose of such partnership, entity, plan, or arrangement is the avoidance or evasion of Federal income tax."],[0,"(3) Secretarial list"],[1,"The Secretary may prescribe a list of positions which the Secretary believes do not meet 1 or more of the standards specified in paragraph (2)(B)(i), section 6664(d)(3), and section 6694(a)(1). Such list (and any revisions thereof) shall be published in the Federal Register or the Internal Revenue Bulletin."],[0,"(e) Substantial valuation misstatement under chapter 1"],[0,"(1) In general"],[1,"For purposes of this section, there is a substantial valuation misstatement under chapter 1 if—"],[2,"(A) the value of any property (or the adjusted basis of any property) claimed on any return of tax imposed by chapter 1 is 150 percent or more of the amount determined to be the correct amount of such valuation or adjusted basis (as the case may be), or"],[2,"(B)(i) the price for any property or services (or for the use of property) claimed on any such return in connection with any transaction between persons described in section 482 is 200 percent or more (or 50 percent or less) of the amount determined under section 482 to be the correct amount of such price, or"],[2,"(ii) the net section 482 transfer price adjustment for the taxable year exceeds the lesser of $5,000,000 or 10 percent of the taxpayer's gross receipts."],[0,"(2) Limitation"],[1,"No penalty shall be imposed by reason of subsection (b)(3) unless the portion of the underpayment for the taxable year attributable to substantial valuation misstatements under chapter 1 exceeds $5,000 ($10,000 in the case of a corporation other than an S corporation or a personal holding company (as defined in section 542))."],[0,"(3) Net section 482 transfer price adjustment"],[1,"For purposes of this subsection—"],[0,"(A) In general"],[2,"The term \"net section 482 transfer price adjustment\" means, with respect to any taxable year, the net increase in taxable income for the taxable year (determined without regard to any amount carried to such taxable year from another taxable year) resulting from adjustments under section 482 in the price for any property or services (or for the use of property)."],[0,"(B) Certain adjustments excluded in determining threshold"],[2,"For purposes of determining whether the threshold requirements of paragraph (1)(B)(ii) are met, the following shall be excluded:"],[3,"(i) Any portion of the net increase in taxable income referred to in subparagraph (A) which is attributable to any redetermination of a price if—"],[4,"(I) it is established that the taxpayer determined such price in accordance with a specific pricing method set forth in the regulations prescribed under section 482 and that the taxpayer's use of such method was reasonable,"],[4,"(II) the taxpayer has documentation (which was in existence as of the time of filing the return) which sets forth the determination of such price in accordance with such a method and which establishes that the use of such method was reasonable, and"],[4,"(III) the taxpayer provides such documentation to the Secretary within 30 days of a request for such documentation."],[3,"(ii) Any portion of the net increase in taxable income referred to in subparagraph (A) which is attributable to a redetermination of price where such price was not determined in accordance with such a specific pricing method if—"],[4,"(I) the taxpayer establishes that none of such pricing methods was likely to result in a price that would clearly reflect income, the taxpayer used another pricing method to determine such price, and such other pricing method was likely to result in a price that would clearly reflect income,"],[4,"(II) the taxpayer has documentation (which was in existence as of the time of filing the return) which sets forth the determination of such price in accordance with such other method and which establishes that the requirements of subclause (I) were satisfied, and"],[4,"(III) the taxpayer provides such documentation to the Secretary within 30 days of request for such documentation."],[3,"(iii) Any portion of such net increase which is attributable to any transaction solely between foreign corporations unless, in the case of any such corporations, the treatment of such transaction affects the determination of income from sources within the United States or taxable income effectively connected with the conduct of a trade or business within the United States."],[0,"(C) Special rule"],[2,"If the regular tax (as defined in section 55(c)) imposed by chapter 1 on the taxpayer is determined by reference to an amount other than taxable income, such amount shall be treated as the taxable income of such taxpayer for purposes of this paragraph."],[0,"(D) Coordination with reasonable cause exception"],[2,"For purposes of section 6664(c) the taxpayer shall not be treated as having reasonable cause for any portion of an underpayment attributable to a net section 482 transfer price adjustment unless such taxpayer meets the requirements of clause (i), (ii), or (iii) of subparagraph (B) with respect to such portion."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/6662?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§6662. Imposition of accuracy-related penalty on underpayments","tname":"Internal Revenue Code","by":{"0":"passim, 2, 3, 4, 35, 4, 38, 2, 3, 4, 23, 39, 38, 3, 2, 4, 24, 41, 4, 13, 2, 4, 39, 4","1":"10, 15, 21, 22, 23, 22, 7, 22, 21, 21, 22, 12, 11, passim, 11, 21, 22"}},{"t":"usc","label":"26 U.S.C. § 6664","url":"https://www.law.cornell.edu/uscode/text/26/6664","subs":["(c)","(c)(1)"],"stext":{"head":"§6664. Definitions and special rules","paras":[[0,"(a) Underpayment"],[0,"For purposes of this part, the term \"underpayment\" means the amount by which any tax imposed by this title exceeds the excess of—"],[1,"(1) the sum of—"],[2,"(A) the amount shown as the tax by the taxpayer on his return, plus"],[2,"(B) amounts not so shown previously assessed (or collected without assessment), over"],[1,"(2) the amount of rebates made."],[0,"For purposes of paragraph (2), the term \"rebate\" means so much of an abatement, credit, refund, or other repayment, as was made on the ground that the tax imposed was less than the excess of the amount specified in paragraph (1) over the rebates previously made. A rule similar to the rule of section 6211(b)(4) shall apply for purposes of this subsection."],[0,"(b) Penalties applicable only where return filed"],[0,"The penalties provided in this part shall apply only in cases where a return of tax is filed (other than a return prepared by the Secretary under the authority of section 6020(b))."],[0,"(c) Reasonable cause exception for underpayments"],[0,"(1) In general"],[1,"No penalty shall be imposed under section 6662 or 6663 with respect to any portion of an underpayment if it is shown that there was a reasonable cause for such portion and that the taxpayer acted in good faith with respect to such portion."],[0,"(2) Exception"],[1,"Paragraph (1) shall not apply to any portion of an underpayment which is attributable to one or more transactions described in section 6662(b)(6) or to any disallowance of a deduction described in section 6662(b)(10)."],[0,"(3) Special rule for certain valuation overstatements"],[1,"In the case of any underpayment attributable to a substantial or gross valuation overstatement under chapter 1 with respect to charitable deduction property, paragraph (1) shall not apply. The preceding sentence shall not apply to a substantial valuation overstatement under chapter 1 if—"],[2,"(A) the claimed value of the property was based on a qualified appraisal made by a qualified appraiser, and"],[2,"(B) in addition to obtaining such appraisal, the taxpayer made a good faith investigation of the value of the contributed property."],[0,"(4) Definitions"],[1,"For purposes of this subsection—"],[0,"(A) Charitable deduction property"],[2,"The term \"charitable deduction property\" means any property contributed by the taxpayer in a contribution for which a deduction was claimed under section 170. For purposes of paragraph (3), such term shall not include any securities for which (as of the date of the contribution) market quotations are readily available on an established securities market."],[0,"(B) Qualified appraisal"],[2,"The term \"qualified appraisal\" has the meaning given such term by section 170(f)(11)(E)(i)."],[0,"(C) Qualified appraiser"],[2,"The term \"qualified appraiser\" has the meaning given such term by section 170(f)(11)(E)(ii)."],[0,"(d) Reasonable cause exception for reportable transaction understatements"],[0,"(1) In general"],[1,"No penalty shall be imposed under section 6662A with respect to any portion of a reportable transaction understatement if it is shown that there was a reasonable cause for such portion and that the taxpayer acted in good faith with respect to such portion."],[0,"(2) Exception"],[1,"Paragraph (1) shall not apply to any portion of a reportable transaction understatement which is attributable to one or more transactions described in section 6662(b)(6)."],[0,"(3) Special rules"],[1,"Paragraph (1) shall not apply to any reportable transaction understatement unless—"],[2,"(A) the relevant facts affecting the tax treatment of the item are adequately disclosed in accordance with the regulations prescribed under section 6011,"],[2,"(B) there is or was substantial authority for such treatment, and"],[2,"(C) the taxpayer reasonably believed that such treatment was more likely than not the proper treatment."],[1,"A taxpayer failing to adequately disclose in accordance with section 6011 shall be treated as meeting the requirements of subparagraph (A) if the penalty for such failure was rescinded under section 6707A(d)."],[0,"(4) Rules relating to reasonable belief"],[1,"For purposes of paragraph (3)(C)—"],[0,"(A) In general"],[2,"A taxpayer shall be treated as having a reasonable belief with respect to the tax treatment of an item only if such belief—"],[3,"(i) is based on the facts and law that exist at the time the return of tax which includes such tax treatment is filed, and"],[3,"(ii) relates solely to the taxpayer's chances of success on the merits of such treatment and does not take into account the possibility that a return will not be audited, such treatment will not be raised on audit, or such treatment will be resolved through settlement if it is raised."],[0,"(B) Certain opinions may not be relied upon"],[0,"(i) In general"],[3,"An opinion of a tax advisor may not be relied upon to establish the reasonable belief of a taxpayer if—"],[4,"(I) the tax advisor is described in clause (ii), or"],[4,"(II) the opinion is described in clause (iii)."],[0,"(ii) Disqualified tax advisors"],[3,"A tax advisor is described in this clause if the tax advisor—"],[4,"(I) is a material advisor (within the meaning of section 6111(b)(1)) and participates in the organization, management, promotion, or sale of the transaction or is related (within the meaning of section 267(b) or 707(b)(1)) to any person who so participates,"],[4,"(II) is compensated directly or indirectly by a material advisor with respect to the transaction,"],[4,"(III) has a fee arrangement with respect to the transaction which is contingent on all or part of the intended tax benefits from the transaction being sustained, or"],[4,"(IV) as determined under regulations prescribed by the Secretary, has a disqualifying financial interest with respect to the transaction."],[0,"(iii) Disqualified opinions"],[3,"For purposes of clause (i), an opinion is disqualified if the opinion—"],[4,"(I) is based on unreasonable factual or legal assumptions (including assumptions as to future events),"],[4,"(II) unreasonably relies on representations, statements, findings, or agreements of the taxpayer or any other person,"],[4,"(III) does not identify and consider all relevant facts, or"],[4,"(IV) fails to meet any other requirement as the Secretary may prescribe."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/6664?type=usc&year=mostrecent&link-type=html"},"head":"§6664. Definitions and special rules","tname":"Internal Revenue Code","by":{"0":"35","1":"8, 15, 19"}},{"t":"usc","label":"26 U.S.C. § 7701","url":"https://www.law.cornell.edu/uscode/text/26/7701","subs":["(o)(5)(A)"],"by":{"0":"17"}},{"t":"law","label":"Pub. L. No. 109-280","url":"https://www.govinfo.gov/link/plaw/109/public/280","by":{"0":"4"}},{"t":"law","label":"Pub. L. No. 97-248","url":"https://www.govinfo.gov/link/statute/96/324","by":{"0":"8"}},{"t":"law","label":"Pub. L. No. 105-34","url":"https://www.govinfo.gov/link/plaw/105/public/34","by":{"0":"12, 22","1":"3"}},{"t":"case","label":"Burgess v. United States","cite":"553 U.S. 124","y":2008,"id":"2007/06-11429","sc":1,"sum":"The Court upheld the sentencing hike, stating that the definition of a felony drug offense in 12 U.S.C. 841 as punishable by imprisonment for more than one year was controlling regardless of whether South Carolina classified the offense as a felony or a misdemeanor.","sumSrc":"Oyez","by":{"1":"12"}},{"t":"case","label":"Chapman Glen Ltd. v. Commissioner","cite":"2013 WL 2319282","y":2013,"court":"May 28","op":1,"by":{"1":"13"}},{"t":"case","label":"Chickasaw Nation v. United States","cite":"534 U.S. 84","y":2001,"id":"2001/00-507","sc":1,"sum":"The Court held that Indian Regulatory Gaming Act does not create such an exemption. The Court reasoned that despite its parenthetical reference, the language outside the parenthetical was unambiguous and the subsection applied only to Internal Revenue Code provisions that concerned the reporting and withholding of taxes.","sumSrc":"Oyez","by":{"1":"11"}},{"t":"case","label":"Commissioner v. Acker","cite":"361 U.S. 87","y":1959,"id":"1959/13","sc":1,"sum":"Under the Internal Revenue Code of 1939, the failure of.a taxpayer, without reasonable cause, to file a declaration of estimated income tax, as required by § 58, subjects him to the addition to the tax prescribed by § 294 (d) (1) (A) for failure to file the declaration;. but it does not subject him also to the addition to the tax prescribed by § 294 (d) (2) for the filing of a \"substantial underestimate\" of his tax. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"Fulman v. United States","cite":"434 U.S. 528","y":1978,"id":"1977/76-1137","sc":1,"sum":"The provision of Treas. Reg. § 1.562-1 (a) that a personal holding company's distribution of appreciated property to its shareholders results, under §§ 561 and 562 of the Internal Revenue Code of 1954, in a dividends-paid deduction limited to an amount that is the adjusted tax basis of the property in the hands of the company at the time of the distribution held valid as having a reasonable basis, as against the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"Genesis Healthcare Corp. v. Symczyk","cite":"133 S. Ct. 1523","y":2013,"id":"2012/11-1059","sc":1,"sum":"The Court held that a collective action suit on behalf of other \"similarly situated\" employees becomes moot when the individual claim does.","sumSrc":"Oyez","by":{"1":"5"}},{"t":"case","label":"Greenlaw v. United States","cite":"554 U.S. 237","y":2008,"id":"2007/07-330","sc":1,"sum":"The Court stated that the Eighth Circuit could not order the district court to increase Greenlaw's sentence without a request from the government to do so. The Court pointed to several of its precedents for the rule that a remedy in favor the appellee, in this case the government, can only be justified if the appellee brings a cross-appeal.","sumSrc":"Oyez","by":{"1":"5"}},{"t":"case","label":"Powers v. Commissioner","cite":"312 U.S. 259","y":1941,"id":"scdb/1940-116","sc":1,"op":1,"sum":"Detdrmination of the criterion of \"value\" for the purposes of the gift tax under the Revenue Act of 1932 is a question of law, and a decision of the Board of Tax Appeals that in the case of single-premium policies of life insurance, irrevocably\" assigned as gifts shortly after issuance, the value of the gifts was the cash surrender value of the policies, was properly reversed by the Circuit Court of Appeals as \"not …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13"}},{"t":"case","label":"Reiter v. Sonotone Corp.","cite":"442 U.S. 330","y":1979,"id":"1978/78-690","sc":1,"op":2,"sum":"Consumers who pay a higher price for goods purchased for personal use as a result of antitrust violations sustain an injury in their \"property\" within the meaning of § 4.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"11"}},{"t":"case","label":"Whitehouse Hotel Ltd. P’ship v. Commissioner","cite":"615 F.3d 321","y":2010,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/615/321/","by":{"1":"13, 16"}},{"t":"usc","label":"26 U.S.C. § 168","url":"https://www.law.cornell.edu/uscode/text/26/168","subs":["(c)"],"by":{"1":"14"}},{"t":"usc","label":"26 U.S.C. § 170","url":"https://www.law.cornell.edu/uscode/text/26/170","by":{"1":"13"}},{"t":"usc","label":"26 U.S.C. § 742","url":"https://www.law.cornell.edu/uscode/text/26/742","by":{"1":"4"}},{"t":"usc","label":"26 U.S.C. § 1011","url":"https://www.law.cornell.edu/uscode/text/26/1011","subs":["(a)"],"by":{"1":"14"}},{"t":"usc","label":"26 U.S.C. § 1012","url":"https://www.law.cornell.edu/uscode/text/26/1012","subs":["(a)"],"stext":{"head":"§1012. Basis of property—cost","paras":[[0,"(a) In general"],[0,"The basis of property shall be the cost of such property, except as otherwise provided in this subchapter and subchapters C (relating to corporate distributions and adjustments), K (relating to partners and partnerships), and P (relating to capital gains and losses)."],[0,"(b) Special rule for apportioned real estate taxes"],[0,"The cost of real property shall not include any amount in respect of real property taxes which are treated under section 164(d) as imposed on the taxpayer."],[0,"(c) Determinations by account"],[0,"(1) In general"],[1,"In the case of the sale, exchange, or other disposition of a specified security on or after the applicable date, the conventions prescribed by regulations under this section shall be applied on an account by account basis."],[0,"(2) Application to certain regulated investment companies"],[0,"(A) In general"],[2,"Except as provided in subparagraph (B), any stock for which an average basis method is permissible under this section which is acquired before January 1, 2012, shall be treated as a separate account from any such stock acquired on or after such date."],[0,"(B) Election for treatment as single account"],[2,"If a regulated investment company described in subparagraph (A) elects to have this subparagraph apply with respect to one or more of its stockholders—"],[3,"(i) subparagraph (A) shall not apply with respect to any stock in such regulated investment company held by such stockholders, and"],[3,"(ii) all stock in such regulated investment company which is held by such stockholders shall be treated as covered securities described in section 6045(g)(3) without regard to the date of the acquisition of such stock."],[2,"A rule similar to the rule of the preceding sentence shall apply with respect to a broker holding such stock as a nominee."],[0,"(3) Definitions"],[1,"For purposes of this section, the terms \"specified security\" and \"applicable date\" shall have the meaning given such terms in section 6045(g)."],[0,"(d) Average basis for stock acquired pursuant to a dividend reinvestment plan"],[0,"(1) In general"],[1,"In the case of any stock acquired after December 31, 2011, in connection with a dividend reinvestment plan, the basis of such stock while held as part of such plan shall be determined using one of the methods which may be used for determining the basis of stock in a regulated investment company."],[0,"(2) Treatment after transfer"],[1,"In the case of the transfer to another account of stock to which paragraph (1) applies, such stock shall have a cost basis in such other account equal to its basis in the dividend reinvestment plan immediately before such transfer (properly adjusted for any fees or other charges taken into account in connection with such transfer)."],[0,"(3) Separate accounts; election for treatment as single account"],[0,"(A) In general"],[2,"Rules similar to the rules of subsection (c)(2) shall apply for purposes of this subsection."],[0,"(B) Average basis method"],[2,"Notwithstanding paragraph (1), in the case of an election under rules similar to the rules of subsection (c)(2)(B) with respect to stock held in connection with a dividend reinvestment plan, the average basis method is permissible with respect to all such stock without regard to the date of the acquisition of such stock."],[0,"(4) Dividend reinvestment plan"],[1,"For purposes of this subsection—"],[0,"(A) In general"],[2,"The term \"dividend reinvestment plan\" means any arrangement under which dividends on any stock are reinvested in stock identical to the stock with respect to which the dividends are paid."],[0,"(B) Initial stock acquisition treated as acquired in connection with plan"],[2,"Stock shall be treated as acquired in connection with a dividend reinvestment plan if such stock is acquired pursuant to such plan or if the dividends paid on such stock are subject to such plan."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/1012?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1012. Basis of property—cost","tname":"Internal Revenue Code","by":{"1":"14, 11, 13, 14"}},{"t":"usc","label":"26 U.S.C. § 1016","url":"https://www.law.cornell.edu/uscode/text/26/1016","by":{"1":"14"}},{"t":"usc","label":"26 U.S.C. § 6662A","url":"https://www.law.cornell.edu/uscode/text/26/6662A","subs":["(e)","(e)(2)(B)"],"by":{"1":"23, 22, 23"}},{"t":"usc","label":"26 U.S.C. § 6701","url":"https://www.law.cornell.edu/uscode/text/26/6701","by":{"1":"22, 22"}},{"t":"usc","label":"26 U.S.C. § 6707A","url":"https://www.law.cornell.edu/uscode/text/26/6707A","by":{"1":"23"}}]};